/**
 * Bumpa auth helpers.
 *
 * Bumpa does NOT use an OAuth2 authorization-code flow. Credentials are
 * API keys generated by the store owner inside the Bumpa web app under
 * Store → API key. The key is passed as a Bearer token in the
 * `Authorization` header on every request.
 *
 * This means:
 *  - `getAuthUrl` returns an informational URL pointing to the Bumpa web app.
 *  - `exchangeCode` throws a descriptive error — callers should POST the API
 *    key directly to /v1/connections with `{ platform: 'bumpa', credentials:
 *    { accessToken: '<api-key>' } }`.
 *  - Keys do not expire, so `refreshCredentials` is a no-op.
 *
 * Docs: https://docs.bumpa.io
 */

import type { Credentials } from '@opensteward/shared'

/** Informational URL where the user can generate an API key. */
export function buildAuthUrl(): string {
  return 'https://app.getbumpa.com/store/api-key'
}

export function exchangeCode(): Promise<Credentials> {
  throw new Error(
    'Bumpa does not use an OAuth code-exchange flow. ' +
      'Generate an API key in the Bumpa web app (Store → API key), ' +
      'then POST it to /v1/connections with body ' +
      '`{ platform: "bumpa", credentials: { accessToken: "<api-key>" } }`.',
  )
}
